# check_machine.ps1 - is this machine ready to build and play Tower of Doom II: Cybercity? (docs/220)
#
#   powershell -ExecutionPolicy Bypass -File tools\migrate\check_machine.ps1            # quick (sizes)
#   powershell -ExecutionPolicy Bypass -File tools\migrate\check_machine.ps1 -FullHash  # re-hash the private root
#
# Read-only. Prints PASS / WARN / FAIL per item and exits 1 on any FAIL. A FAIL blocks building or
# playing; a WARN only matters for art / sound / extraction work. Runs on the old laptop too (as a
# control). Adapted from Map One's check (its docs/174): the shared toolchain rows are the same, the
# Tower II rows check the private root, its junctions and the game's child junction.
param(
    [string]$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path,
    [string]$SteamCommon = 'C:\Program Files (x86)\Steam\steamapps\common',
    [string]$Tod2Root = 'C:\BO3Tools\TOD2Cybercity',
    [string]$RootManifest = '',
    [switch]$FullHash
)
$ErrorActionPreference = 'Continue'
$script:fails = 0; $script:warns = 0
function Pass($m) { Write-Host "  PASS  $m" -ForegroundColor Green }
function Warn($m) { Write-Host "  WARN  $m" -ForegroundColor Yellow; $script:warns++ }
function Fail($m) { Write-Host "  FAIL  $m" -ForegroundColor Red; $script:fails++ }
function Check([bool]$ok, [string]$pass, [string]$bad, [switch]$WarnOnly) {
    if ($ok) { Pass $pass } elseif ($WarnOnly) { Warn $bad } else { Fail $bad }
}
function Cmd($n) { (Get-Command $n -ErrorAction SilentlyContinue) }

$H = $env:USERPROFILE
$ReposDir = Split-Path $RepoRoot -Parent
$Game  = Join-Path $SteamCommon 'Call of Duty Black Ops III'
$Tools = Join-Path $SteamCommon 'Call of Duty Black Ops III 455130'
$Map = 'zm_tod2_cybercity'

Write-Host "== Windows"
Check ($H -eq 'C:\Users\jorda') "profile is C:\Users\jorda" "profile is $H - Tower II tools and build gates hardcode C:\Users\jorda (docs/220 'Paths')"
Check ($RepoRoot.TrimEnd('\') -eq 'C:\Users\jorda\Repositories\tower_of_doom_II_cybercity') "repo at the path .tod2-workspace.json names" "repo is at $RepoRoot - the private root's marker names C:\Users\jorda\Repositories\tower_of_doom_II_cybercity and the build refuses any other"
$lpe = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' -Name LongPathsEnabled -ErrorAction SilentlyContinue).LongPathsEnabled
Check ($lpe -eq 1) 'long paths enabled' 'long paths OFF - admin PowerShell: Set-ItemProperty HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem LongPathsEnabled 1'
$free = (Get-PSDrive C).Free / 1e9
Check ($free -ge 60) ("C: free {0:N0} GB" -f $free) ("C: free only {0:N0} GB - the first full build regenerates the converter cache and the LED bake needs room" -f $free) -WarnOnly

Write-Host "== Toolchain"
Check ([bool](Cmd git)) "git: $(git --version 2>$null)" 'git missing (winget install Git.Git)'
$lfs = (git lfs version 2>$null); Check ([bool]$lfs) "git-lfs: $lfs" 'git-lfs missing (comes with Git for Windows) - Blender masters would be pointer files'
Check ("$(git config --global core.longpaths)" -eq 'true') 'git core.longpaths=true' 'git config --global core.longpaths true' -WarnOnly
Check ([bool]"$(git config --global user.name)") "git identity: $(git config --global user.name)" 'git user.name not set - commits will fail' -WarnOnly
$nv = (node --version 2>$null)
Check ($nv -match '^v(\d+)' -and [int]$matches[1] -ge 24) "node $nv" "node $nv - need Node 24+ (most build gates are node)"
$pyv = (python --version 2>&1)
Check ("$pyv" -match '^Python 3\.(1[1-9])') "$pyv" "python missing or too old ($pyv) - install Python 3.14 'Add to PATH'"
Check ("$pyv" -match '^Python 3\.14') 'python is 3.14 (same as the old laptop)' "$pyv is not 3.14 - gates compare regenerated bytes; use the old laptop's 3.14.7" -WarnOnly
& python -c "import numpy, PIL, scipy, soundfile, fontTools, resvg_py, lz4.block; from lupa.lua51 import LuaRuntime" 2>$null
Check ($LASTEXITCODE -eq 0) 'python packages: numpy pillow scipy soundfile lupa fonttools resvg_py lz4' 'python packages missing - python -m pip install -r tools\migrate\requirements.txt (fonttools / resvg_py / lz4 are Tower II gates Map One never needed)'
$want = @{}
foreach ($l in Get-Content (Join-Path $PSScriptRoot 'requirements.txt')) { if ($l -match '^([A-Za-z0-9_.-]+)==([^\s#]+)') { $want[$matches[1].ToLower().Replace('_', '-')] = $matches[2] } }
$have = @{}
foreach ($l in (& python -m pip list --format=freeze --disable-pip-version-check 2>$null)) { if ("$l" -match '^([A-Za-z0-9_.-]+)==(.+)$') { $have[$matches[1].ToLower().Replace('_', '-')] = $matches[2] } }
$off = @($want.Keys | Where-Object { $have[$_] -ne $want[$_] } | ForEach-Object { "$_ $($have[$_]) (want $($want[$_]))" })
Check ($off.Count -eq 0) 'python package versions match the old laptop (gates compare regenerated bytes)' "python package versions differ: $($off -join ', ') - byte-exact gates regenerate PNG/WAV/xmodel_bin with these: python -m pip install -r tools\migrate\requirements.txt"
Check ("$nv" -eq 'v24.18.0') 'node is v24.18.0 (same as the old laptop)' "node $nv is not v24.18.0 - gen_kill_feel_art.js --check byte-compares zlib output; install 24.18.0 if that gate goes red" -WarnOnly
Check ([bool](Cmd ffmpeg) -and [bool](Cmd ffprobe)) "ffmpeg + ffprobe on PATH: $((Cmd ffmpeg).Source)" 'ffmpeg / ffprobe not both on PATH - black_market_vo/pick.py --check and the sound generators need them (winget install Gyan.FFmpeg --version 8.1.2)'
$blender = 'C:\Program Files\Blender Foundation\Blender 4.2\blender.exe'
Check (Test-Path $blender) 'Blender 4.2 LTS at the scripted path' "Blender 4.2 LTS not at $blender - every art/model script calls this exact path" -WarnOnly
$addons = Join-Path $env:APPDATA 'Blender Foundation\Blender\4.2\scripts\addons'
Check (Test-Path (Join-Path $addons 'BetterBetterBlenderCOD')) 'PyCoD #1: BetterBetterBlenderCOD in the Blender 4.2 addons (~23 Tower II gate closures import it)' 'BetterBetterBlenderCOD missing from %APPDATA%\Blender Foundation\Blender\4.2\scripts\addons - many build gates fail without it (Map One import_bundle.ps1 restores it)'
Check (Test-Path (Join-Path $ReposDir 'test+map\tmp\blender-cod\io_scene_cod')) 'PyCoD #2: test+map\tmp\blender-cod (verify_perk_machine_presentation)' 'test+map\tmp\blender-cod missing - verify_perk_machine_presentation fails without it (Map One bundle repos\test+map)'
Check (Test-Path (Join-Path $addons 'io_scene_cast')) 'Blender Cast addon (BO6 imports)' 'io_scene_cast missing from the Blender 4.2 addons (BO6 / Apex extraction only)' -WarnOnly
Check (Test-Path 'C:\Program Files\7-Zip\7z.exe') '7-Zip at C:\Program Files\7-Zip\7z.exe (the keeper / dealer gates call this exact path)' '7-Zip missing at C:\Program Files\7-Zip\7z.exe - keeper/install_keeper.py and dealer_boss/install.py --check fail every build (winget install 7zip.7zip)'
$t7 = Get-Item (Join-Path $H 'Downloads\T7 Assets V2.8.rar') -ErrorAction SilentlyContinue
Check ($t7 -and $t7.Length -eq 58083230502) 'Downloads\T7 Assets V2.8.rar present (58,083,230,502 B; the keeper / dealer gates re-extract from it every build)' "Downloads\T7 Assets V2.8.rar missing or not 58,083,230,502 bytes$(if ($t7) { " (it is $($t7.Length))" }) - the keeper / dealer build gates fail without it (bundle downloads\)"
Check ([bool][Environment]::GetEnvironmentVariable('ELEVENLABS_API_KEY', 'User')) 'ELEVENLABS_API_KEY set (voice / SFX generators)' 'ELEVENLABS_API_KEY not set - only the ElevenLabs voice/SFX generators need it; credentials are never copied' -WarnOnly

Write-Host "== Steam / BO3"
Check (Test-Path (Join-Path $Game 'BlackOps3.exe')) "BO3 at $Game" "BO3 not found at $Game"
Check (Test-Path (Join-Path $Tools 'bin\modlauncher.exe')) "Mod Tools at $Tools" "Mod Tools not at $Tools - the private root's 123 junctions point into this exact folder (finish Map One's migration first)"
foreach ($dll in 'msvcr110.dll', 'msvcp110.dll', 'vcomp110.dll', 'd3dx9_43.dll') {
    $found = (Test-Path "$env:WINDIR\System32\$dll") -or (Test-Path (Join-Path $Tools "bin\$dll")) -or (Test-Path (Join-Path $Tod2Root "bin\$dll"))
    $which = if ($dll -like 'd3dx*') { 'DirectX End-User Runtime (June 2010)' } else { 'Visual C++ 2012 Redistributable (x64)' }
    Check $found "runtime $dll" "runtime $dll missing - install the $which (Steam > Mod Tools > Play once and accept the admin prompt)"
}
$gu = Get-Item (Join-Path $Game 'usermaps') -Force -ErrorAction SilentlyContinue
Check ([bool]$gu) 'game\usermaps exists (Map One import: junction to the tools usermaps)' 'game\usermaps missing - finish Map One''s migration (its import makes the usermaps junction)'
$link = Get-Item (Join-Path $Game "usermaps\$Map") -Force -ErrorAction SilentlyContinue
$wantLink = Join-Path $Tod2Root "usermaps\$Map"
Check ($link -and ($link.Attributes -band [IO.FileAttributes]::ReparsePoint) -and "$(@($link.Target)[0])".TrimEnd('\') -eq $wantLink) "game usermaps\$Map -> $wantLink" "game usermaps\$Map is not a junction to $wantLink - the game will not see Tower II builds (import_bundle.ps1 creates it)"
Check (-not (Test-Path (Join-Path $Tools "usermaps\zm_tower_of_doom\zone\$Map.ff"))) 'no Tower II output inside Map One''s usermap' 'a Tower II fastfile sits in Map One''s usermap - isolation breach (CLAUDE.md hard rule 1)' -WarnOnly
$cte = (Get-ItemProperty 'HKCU:\Software\Treyarch\Radiant\Prefs' -ErrorAction SilentlyContinue).Controller_Enabled
Check ("$cte" -eq 'false') 'Radiant Controller_Enabled=false' 'Radiant Controller_Enabled is not false - a gamepad press opens Preferences and stalls the LED bake (Map One registry\treyarch.reg)' -WarnOnly

Write-Host "== Private Mod Tools root"
$marker = Join-Path $Tod2Root '.tod2-workspace.json'
Check (Test-Path $marker) "workspace marker $marker" "no $marker - run import_bundle.ps1 (NEVER setup_tod2_workspace.ps1 on a migrated machine: it copies today's Steam root, not Tower II's)"
if (Test-Path $marker) {
    $m = Get-Content $marker -Raw | ConvertFrom-Json
    Check ($m.map -eq $Map -and $m.repository -eq $RepoRoot.TrimEnd('\')) "marker binds $($m.map) to $($m.repository)" "marker names map '$($m.map)' / repo '$($m.repository)', not $Map / $RepoRoot - tod2_workspace.ps1 refuses to build"
    # the same structural checks tod2_workspace.ps1 Resolve-Tod2Root makes before every build
    $guarded = 'bin', 'gdtdb', 'source_data', 'share\assetconvert', 'share\raw\maps', 'share\raw\fx', 'share\raw\sound', 'sound', 'sw4', 'usermaps', 'map_source', 'pc'
    $rp = @()
    foreach ($d in $guarded) {
        $p = Join-Path $Tod2Root $d
        if (Test-Path -LiteralPath $p) {
            if ((Get-Item -LiteralPath $p -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) { $rp += $d }
            elseif (@(Get-ChildItem -LiteralPath $p -Recurse -Force -Attributes ReparsePoint -ErrorAction SilentlyContinue | Select-Object -First 1).Count) { $rp += "$d (inside)" }
        }
    }
    Check ($rp.Count -eq 0) 'no junctions inside the private writable folders' "junctions inside private writable folders: $($rp -join ', ') - the build's isolation guard refuses"
    $sh = @('share\assetconvert\ToolsGfx\shaders_modtools', 'share\assetconvert\shaders', 'share\assetconvert\preshader') | Where-Object { -not (Get-ChildItem -LiteralPath (Join-Path $Tod2Root $_) -File -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1) }
    Check (@($sh).Count -eq 0) 'private stock shader binaries present' "missing private shader binaries: $($sh -join ', ') - the converter cannot rebuild them"
    Check (Test-Path (Join-Path $Tod2Root 'sw4\textures\tv_lookup.tif')) 'private sw4 texture library present' 'sw4\textures\tv_lookup.tif missing from the private root'
    Check (Test-Path (Join-Path $Tod2Root 'bin\linker_modtools.exe')) 'private linker present' 'bin\linker_modtools.exe missing from the private root'
}
if ($RootManifest -eq '') { $RootManifest = Join-Path $RepoRoot 'tmp\migration\root_manifest.json' }
if (Test-Path $RootManifest) {
    $a = @((Join-Path $PSScriptRoot 'bundle_tool.py'), 'root-verify', '--manifest', $RootManifest, '--root', $Tod2Root)
    if (-not $FullHash) { $a += '--quick' }
    & python @a | Where-Object { "$_" -notmatch '^\s+verify:' } | ForEach-Object { Write-Host "        $_" }
    Check ($LASTEXITCODE -eq 0) "every transferred private-root file present$(if ($FullHash) { ' and sha1-identical' } else { ' (sizes; -FullHash re-hashes)' }), every junction resolves" 'private root: files missing/differing or junctions broken (listed above) - re-run import_bundle.ps1 (it never replaces files that are newer here)'
} else {
    Warn "no root manifest at $RootManifest (normal on the OLD laptop; on the new one import_bundle.ps1 puts it there)"
}

Write-Host "== Repos"
Check (Test-Path (Join-Path $RepoRoot '.git')) "repo at $RepoRoot" "repo not found at $RepoRoot"
if (Test-Path (Join-Path $RepoRoot '.git')) {
    $br = git -C $RepoRoot rev-parse --abbrev-ref HEAD
    Check ($br -eq 'main') "branch $br" "on branch $br (Tower II work happens on main)" -WarnOnly
    $gone = @(git -C $RepoRoot ls-files --deleted).Count
    Check ($gone -eq 0) 'checkout complete (no tracked file missing)' "$gone tracked files are missing - an interrupted clone: delete the folder and run import_bundle.ps1 again"
    $ptr = @(git -C $RepoRoot lfs ls-files 2>$null | Where-Object { $_ -match '^\S+ - ' })
    Check ($ptr.Count -eq 0) 'LFS files are real (no pointer stubs)' "$($ptr.Count) LFS files are still pointers - run: git -C `"$RepoRoot`" lfs pull"
    $attr = Get-Content (Join-Path $RepoRoot '.gitattributes') -ErrorAction SilentlyContinue
    Check (@($attr | Where-Object { $_ -match '^\*\s+-text\s*$' }).Count -gt 0) ".gitattributes stores files byte-for-byte (* -text)" ".gitattributes lacks '* -text' - a clone converts line endings and sha-pinned gates fail"
    # two read-only canary gates: fan_props pins the sha256 of a MIXED line-ending GDT (any eol conversion
    # fails it); typeface pins the glyph masters + metrics and needs fonttools
    Push-Location $RepoRoot
    $fp = & python -B (Join-Path $RepoRoot 'tools\fan_props\verify.py') --check 2>&1
    $fpOk = ($LASTEXITCODE -eq 0)
    $tf = & python -B (Join-Path $RepoRoot 'tools\typeface\typeface.py') --check 2>&1
    $tfOk = ($LASTEXITCODE -eq 0)
    Pop-Location
    Check $fpOk 'canary build gate fan_props/verify.py --check (mixed-EOL GDT bytes intact)' "fan_props/verify.py --check failed ($(@($fp)[-1])) - files checked out with converted line endings? .gitattributes must say '* -text'"
    Check $tfOk 'canary build gate typeface.py --check (pinned file bytes intact)' "typeface.py --check failed ($(@($tf)[-1])) - converted line endings, or fonttools missing"
    foreach ($d in 'tmp', 'source_library', 'art', 'model_export') {
        Check (Test-Path (Join-Path $RepoRoot $d)) "repo\$d present" "repo\$d missing (tmp + source_library come from the bundle's repo_extras)" -WarnOnly
    }
}
Check (Test-Path (Join-Path $ReposDir 'tower_of_doom_cybercity\.git')) 'Map One repo present (READ ONLY reference; a few Tower II tools read it)' 'Map One repo missing - finish Map One''s migration' -WarnOnly
Check (Test-Path (Join-Path $ReposDir 'abandoned_cyber_city_zombies\.git')) 'ACC repo present (knowledge base)' 'ACC repo missing - git clone https://github.com/JordanUrbaezLu/abandoned_cyber_city_zombies' -WarnOnly
$venvPy = Join-Path $ReposDir 'tower_of_doom_II_hellbound\tmp\gold_sword_env\Scripts\python.exe'
$mcpOk = $false
if (Test-Path $venvPy) { & $venvPy -c "import mcp, blender_mcp" 2>$null; $mcpOk = ($LASTEXITCODE -eq 0) }
Check $mcpOk 'Blender MCP client venv (gold_sword_env) imports mcp + blender_mcp' 'Blender MCP venv missing/broken (art sessions only; Map One import_bundle.ps1 builds it)' -WarnOnly

Write-Host "== Personal data"
$key = $RepoRoot -replace '[^A-Za-z0-9]', '-'
Check (Test-Path (Join-Path $H ".claude\projects\$key\memory\MEMORY.md")) 'Claude project memory in place' "Claude memory missing at ~\.claude\projects\$key\memory" -WarnOnly

Write-Host ""
if ($script:fails -gt 0) { Write-Host "NOT READY: $($script:fails) FAIL, $($script:warns) WARN" -ForegroundColor Red; exit 1 }
Write-Host "READY TO BUILD: 0 FAIL, $($script:warns) WARN. Next: python tools\run_build_gates.py, then .\tools\build_map.ps1 - the first full build re-converts assets and takes longer" -ForegroundColor Green
exit 0
